(() => {
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const num=v=>v==null?'—':Number(v).toLocaleString('en-IN',{maximumFractionDigits:2});
  const day=v=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(v));
  const today=()=>day(new Date());
  const time=v=>new Date(v).toLocaleString('sv-SE',{timeZone:'Asia/Kolkata'});
  const empty=()=>'<div class="agency-empty"><img class="cw-no-data-art" src="assets/no-data.svg" alt="" aria-hidden="true"><p>No data</p></div>';
  const copyIcon='<svg viewBox="0 0 24 24"><rect x="8" y="3" width="13" height="14" rx="2"/><path d="M16 17v4H3V7h5"/></svg>';
  const searchIcon='<svg viewBox="0 0 24 24"><circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/></svg>';
  const categories=[['lottery','Lottery','◈'],['popular','Popular','★'],['mini-games','Mini Games','✦'],['slots','Slots','▥'],['fishing','Fishing','≈'],['casino','Casino','♠'],['sports','Sports','⚑'],['other','More Games','⊞']];
  const rates=Array.from({length:6},()=>Array(6).fill(null)); // Numeric rates require the user's verified server table.
  const levels=[['L0','0','0','0'],['L1','10','500K','100K'],['L2','15','1,000K','200K'],['L3','30','2.50M','500K'],['L4','45','3.50M','700K'],['L5','50','5M','1,000K'],['L6','60','10M','2M'],['L7','100','100M','20M'],['L8','500','500M','100M'],['L9','1000','1,000M','200M'],['L10','5000','1,500M','300M']];
  const rules=[
    'There are 6 subordinate levels. If A invites B, B is a level 1 subordinate of A. If B invites C, C is level 1 of B and level 2 of A. If C invites D, D is level 1 of C, level 2 of B and level 3 of A.',
    'Share your invitation link or ask your friend to enter your invitation code when registering. A successful registration adds your friend to your level 1 subordinates.',
    'When an invitee registers with your code and completes a qualifying deposit, rewards depend on the invitation conditions below. Only verified completed deposits are counted.',
    "Yesterday's commission is settled according to the configured daily settlement schedule. Completed settlements appear in Commission details and are credited to the wallet.",
    'Your rebate level depends on your team number, team betting and team deposits. Team number is the qualifying number of people in your network; team betting and team deposits are your network totals.',
    'Commission percentages depend on your rebate level and game category. Higher levels offer higher percentages. View the rebate ratio for details.',
    'Additional ranking rewards may be offered to top promotion partners when an active campaign is announced.',
    'The final interpretation of the promotion partner program belongs to Color Win.'
  ];
  function rulePage(){return '<div class="rules-intro"><h2>【Promotion partner】program</h2><p>This activity is valid for a long time</p></div>'+rules.map((text,i)=>`<section class="agency-rule"><div class="rule-number">${String(i+1).padStart(2,'0')}</div><p>${text}</p>${i===5?'<a href="#/promotion/rebate">View rebate ratio »</a>':''}</section>${i===4?'<div class="agency-table-wrap"><table class="agency-level-table"><thead><tr><th>Rebate level</th><th>Team number</th><th>Team betting</th><th>Team deposit</th></tr></thead><tbody>'+levels.map(l=>'<tr><td><span class="level-crown">♛ '+l[0]+'</span></td>'+l.slice(1).map(v=>'<td>'+v+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>':''}`).join('');}
  const summaries=items=>'<div class="agency-summary">'+items.map(([value,label])=>'<div><strong>'+num(value)+'</strong><span>'+label+'</span></div>').join('')+'</div>';
  function mount(action,panel,data,{copy,url}){
    panel.classList.add('agency-layout');panel.innerHTML='';
    const members=data?.members || (data?.direct || []).map(m=>({...m,tier:1}));
    if(action==='rules'){panel.innerHTML=rulePage();return;}
    if(action==='support'){
      panel.innerHTML='<div class="agency-support-banner"><img src="assets/promotion-support.png" alt="Color Win customer service agent"></div><a class="agency-telegram" href="https://t.me/+7nI6oZj0wttkYzRl" target="_blank" rel="noopener noreferrer"><img class="telegram-logo telegram-logo-png" src="assets/social/telegram.png" alt=""><span>Telegram</span><b>›</b></a>';return;
    }
    if(action==='rebate'){
      panel.innerHTML='<nav class="agency-categories" aria-label="Game category">'+categories.map(([id,label,symbol],i)=>`<button type="button" data-category="${id}" aria-pressed="${i===0}" class="${i===0?'active':''}"><span>${symbol}</span>${label}</button>`).join('')+'</nav><div id="rebate-levels"></div>';
      const draw=category=>{panel.querySelector('#rebate-levels').innerHTML=(category==='lottery'?rates:rates.map(()=>Array(6).fill(null))).map((rate,level)=>'<section class="agency-rebate-card"><h2>Rebate level <em>L'+level+'</em></h2><ol>'+rate.map((r,i)=>'<li><span>'+(i+1)+' level lower level commission rebate</span><strong>'+(r==null?'—':r+'%')+'</strong></li>').join('')+'</ol></section>').join('')+(category==='lottery'?'':'<p class="agency-note">Rates for this game category are awaiting configuration.</p>');};
      panel.querySelectorAll('[data-category]').forEach(button=>button.onclick=()=>{panel.querySelectorAll('[data-category]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});draw(button.dataset.category);});draw('lottery');return;
    }
    if(action==='rewards'){
      const rewardRows=[['₹200 ≤ Amount < ₹500','₹1,000','₹38'],['₹500 ≤ Amount < ₹1,000','₹2,500','₹88'],['₹1,000 ≤ Amount < ₹2,500','₹5,000','₹128'],['₹2,500 ≤ Amount < ₹5,000','₹12,500','₹188'],['Amount ≥ ₹5,000','₹25,000','₹388']];
      panel.innerHTML='<div class="agency-rewards-banner"><img src="assets/promotion-rewards.png" alt="Golden reward trophy and coins"><div><strong>Invite friends to get max rewards</strong><span>₹388</span></div></div><div class="reward-metrics"><div>Invitation count <strong>'+num(data?.direct_stats?.registers)+'</strong></div><div>Effective invitation count <strong class="promo-purple">'+num(data?.direct_stats?.first_deposits)+'</strong></div><div>Invitation total bonus <strong class="promo-gold">'+num(data?.reward_total)+'</strong></div></div><a class="agency-record-link" href="#/promotion/new">Invitation record »</a><h2 class="agency-section-title">INVITATION LINK</h2><div class="reward-copy"><input readonly aria-label="Invitation link" value="'+esc(data?.invitation_code?url():'Unavailable')+'"><button type="button" id="reward-copy" aria-label="Copy invitation link">'+copyIcon+'</button></div><section class="reward-rules"><h2><img class="promo-icon" src="assets/promotion-icons/receipt.svg" alt="">Invitation rules</h2><p>If you invite player A, within <em>7 Day</em></p><table class="agency-reward-table"><thead><tr><th colspan="2">When Player A</th><th>You get bonus</th></tr></thead><tbody>'+rewardRows.map((r,i)=>'<tr>'+(i===0?'<td rowspan="5">1st<br>deposit</td>':'')+'<td>'+r[0]+'<br>and Turnover ≥ '+r[1]+'</td><td>'+r[2]+'</td></tr>').join('')+'</tbody></table><p class="reward-warning">Each deposit is eligible for only one bonus.</p><ul><li>Example: Player A first deposits ₹199 and turnover is ₹1,000. This does not meet the bonus conditions.</li><li>The more qualifying friends you invite, the more rewards you can receive.</li><li>Qualifying rewards are credited after verification and settlement.</li></ul></section>';
      panel.querySelector('#reward-copy').onclick=()=>data?.invitation_code?copy(url()):null;return;
    }
    if(action==='new'){
      panel.innerHTML='<div class="agency-period-tabs" role="tablist">'+['Today','Yesterday','This month'].map((label,i)=>'<button type="button" role="tab" aria-selected="'+(i===0)+'" data-period="'+i+'" class="'+(i===0?'active':'')+'">'+label+'</button>').join('')+'</div><div id="new-list"></div>';
      const draw=period=>{const current=today();const yesterday=day(Date.now()-86400000);const list=members.filter(m=>m.tier===1 && (period===0?day(m.created_at)===current:period===1?day(m.created_at)===yesterday:day(m.created_at).slice(0,7)===current.slice(0,7)));panel.querySelector('#new-list').innerHTML=list.length?'<div class="agency-new-list">'+list.map(m=>'<article><div><span>****'+esc(m.phone_last4 || '----')+'</span><span>UID:'+esc(m.uid)+'</span></div><div><strong>Direct subordinates</strong><time>'+esc(time(m.created_at))+'</time></div></article>').join('')+'<p class="agency-no-more">No more</p></div>':empty();};
      panel.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{panel.querySelectorAll('[data-period]').forEach(el=>{el.classList.toggle('active',el===b);el.setAttribute('aria-selected',String(el===b));});draw(Number(b.dataset.period));});draw(0);return;
    }
    if(action==='subordinates'){
      let tier=0,date=today(),query='';
      panel.innerHTML='<form class="agency-search"><input id="agency-uid" inputmode="numeric" placeholder="Search subordinate UID" aria-label="Search subordinate UID"><button type="submit" aria-label="Search">'+searchIcon+'</button></form><div class="agency-filter-row"><button type="button" id="agency-tier">All <span>⌄</span></button><button type="button" id="agency-date">'+date+' <span>⌄</span></button></div><div id="agency-results"></div><p class="agency-note">Date filters registration time. Deposit totals are lifetime verified deposits; betting and commission records are not connected yet.</p>';
      const draw=()=>{const list=members.filter(m=>(!tier||Number(m.tier)===tier)&&day(m.created_at)===date&&(!query||String(m.uid).includes(query)));let count=0,amount=0,first=0,firstAmount=0;list.forEach(m=>{count+=Number(m.deposit_count||0);amount+=Number(m.deposit_amount||0);if(m.deposit_count>0){first++;firstAmount+=Number(m.first_deposit_amount||0);}});panel.querySelector('#agency-results').innerHTML=summaries([[count,'Deposit number'],[amount,'Deposit amount'],[data?.betting_connected?list.reduce((n,m)=>n+Number(m.bet_count||0),0):null,'Number of bettors'],[data?.betting_connected?list.reduce((n,m)=>n+Number(m.bet_amount||0),0):null,'Total bet'],[first,'Number of people making first deposit'],[list.filter(m=>m.deposit_count>0).every(m=>m.first_deposit_amount!=null)?firstAmount:null,'First deposit amount']])+(list.length?list.map(m=>'<article class="agency-member-detail"><h2>UID:'+esc(m.uid)+'<button type="button" data-copy-uid="'+esc(m.uid)+'" aria-label="Copy UID">'+copyIcon+'</button></h2><dl>'+[['Phone','****'+(m.phone_last4||'----')],['Level',m.tier],['Deposit amount',num(m.deposit_amount)],['Bet amount',num(m.bet_amount)],['Commission',num(m.commission)],['Time',time(m.created_at)]].map(([k,v])=>'<div><dt>'+k+'</dt><dd>'+esc(v)+'</dd></div>').join('')+'</dl></article>').join('')+'<p class="agency-no-more">No more</p>':empty());panel.querySelectorAll('[data-copy-uid]').forEach(b=>b.onclick=()=>copy(b.dataset.copyUid));};
      panel.querySelector('form').onsubmit=e=>{e.preventDefault();query=panel.querySelector('#agency-uid').value.trim();draw();};
      panel.querySelector('#agency-tier').onclick=()=>picker(panel,{kind:'tier',value:tier,onConfirm:value=>{tier=Number(value);panel.querySelector('#agency-tier').innerHTML=(tier?'Tier '+tier:'All')+' <span>⌄</span>';draw();}});
      panel.querySelector('#agency-date').onclick=()=>picker(panel,{kind:'date',value:date,onConfirm:value=>{date=value;panel.querySelector('#agency-date').innerHTML=date+' <span>⌄</span>';draw();}});draw();return;
    }
    if(action==='commission'){
      let date=day(Date.now()-86400000);panel.innerHTML='<div class="agency-filter-row single"><button type="button" id="agency-date">'+date+' <span>⌄</span></button></div><div id="commission-records"></div>';
      const draw=()=>{const records=(data?.commissions||[]).filter(r=>r.date===date);panel.querySelector('#commission-records').innerHTML=records.length?records.map(r=>'<section class="agency-settlement"><p>Settlement successful</p><time>'+esc(time(r.settled_at))+'</time><p>The commission has been automatically credited to your balance</p><dl>'+[['Number of bettors',num(r.bettors)+' People'],['Bet amount',num(r.bet_amount)],['Commission payout',num(r.payout)],['Date',r.date+' 00:00:00']].map(([k,v])=>'<div><dt>'+k+'</dt><dd>'+esc(v)+'</dd></div>').join('')+'</dl></section>').join(''):empty();};panel.querySelector('#agency-date').onclick=()=>picker(panel,{kind:'date',value:date,onConfirm:v=>{date=v;panel.querySelector('#agency-date').innerHTML=date+' <span>⌄</span>';draw();}});draw();return;
    }
  }
  function picker(panel,{kind,value,onConfirm}){
    const dialog=document.createElement('dialog');dialog.className='agency-picker';let pending=String(value);
    dialog.innerHTML='<div class="agency-picker-top"><button type="button" data-cancel>Cancel</button><strong>'+(kind==='date'?'Choose a date':'')+'</strong><button type="button" data-confirm>Confirm</button></div>'+(kind==='tier'?'<div class="agency-tier-wheel">'+Array.from({length:7},(_,i)=>'<button type="button" data-tier="'+i+'" class="'+(Number(value)===i?'selected':'')+'">'+(i?'Tier '+i:'All')+'</button>').join('')+'</div>':'<div class="agency-date-wheels"></div>');
    panel.append(dialog);dialog.querySelector('[data-cancel]').onclick=()=>dialog.close();dialog.querySelector('[data-confirm]').onclick=()=>{onConfirm(pending);dialog.close();};dialog.onclick=e=>{if(e.target===dialog)dialog.close();};dialog.addEventListener('close',()=>dialog.remove());
    if(kind==='tier'){dialog.querySelectorAll('[data-tier]').forEach(b=>b.onclick=()=>{pending=b.dataset.tier;dialog.querySelectorAll('[data-tier]').forEach(el=>el.classList.toggle('selected',el===b));});}
    else{
      let [year,month,date]=value.split('-').map(Number);const box=dialog.querySelector('.agency-date-wheels');
      const draw=()=>{const max=new Date(year,month,0).getDate();date=Math.min(date,max);box.innerHTML=[['Year',Array.from({length:new Date().getFullYear()-2019},(_,i)=>2020+i),year],['Month',Array.from({length:12},(_,i)=>i+1),month],['Day',Array.from({length:max},(_,i)=>i+1),date]].map(([label,values,selected])=>'<div class="agency-wheel" role="listbox" aria-label="'+label+'">'+values.map(n=>'<button type="button" role="option" aria-selected="'+(n===selected)+'" data-part="'+label+'" data-value="'+n+'" class="'+(n===selected?'selected':'')+'">'+(label==='Year'?n:String(n).padStart(2,'0'))+'</button>').join('')+'</div>').join('');pending=[year,String(month).padStart(2,'0'),String(date).padStart(2,'0')].join('-');box.querySelectorAll('[data-part]').forEach(b=>b.onclick=()=>{const n=Number(b.dataset.value);if(b.dataset.part==='Year')year=n;else if(b.dataset.part==='Month')month=n;else date=n;draw();});box.querySelectorAll('.selected').forEach(b=>b.scrollIntoView({block:'center'}));};draw();
    }
    dialog.showModal();requestAnimationFrame(()=>dialog.querySelectorAll('.selected').forEach(b=>b.scrollIntoView({block:'center'})));
  }
  window.ColorWinPromotionPages={mount,picker};
})();
